source('R/stile.R')
d<-leggi('cronologia_v3.csv');p<-leggi('proxy_v3.csv');cas<-leggi('casuali_comuni_v3.csv');dep<-d$profondita_cm;age<-d$eta_cal_BP
f<-function(x,a=age)approx(dep,a,xout=x,rule=1)$y
g<-data.frame(profondita_cm=seq(0,160,2));g$eta<-f(g$profondita_cm)
ax<-list(scale_y_reverse(breaks=c(0,40,80,120,160)),scale_x_continuous(breaks=c(0,1000,2000)),labs(x='Età (cal BP)',y='Profondità (cm)'))
salva('M13','F01',ggplot(g,aes(eta,profondita_cm))+geom_path(colour=geo[1],linewidth=.8)+geom_point(data=d,aes(eta_cal_BP,profondita_cm),colour=geo[2],size=3)+ax)
dz<-diff(dep);dt<-diff(age);rates<-data.frame(da=dep[-6],a=dep[-1],rate=10*dz/dt)
salva('M13','F02',ggplot(rates,aes(xmin=da,xmax=a,ymin=0,ymax=rate))+geom_rect(fill=geo[1],colour=paper)+scale_x_continuous(breaks=c(0,40,80,120,160))+scale_y_continuous(labels=fmt,breaks=c(0,.5,1,1.5))+labs(x='Profondità (cm)',y='Accumulo (mm/anno)'))
E<-matrix(cas$z[1:3000],500,6,byrow=TRUE);A<-sweep(sweep(E,2,d$sd_scenario_anni,'*'),2,age,'+');ok<-apply(A,1,function(x)all(diff(x)>0));Aok<-A[ok,,drop=FALSE]
sc<-sapply(1:nrow(Aok),function(i)f(g$profondita_cm,Aok[i,]));qq<-t(apply(sc,1,quantile,c(.025,.5,.975)));band<-data.frame(g,lo=qq[,1],med=qq[,2],hi=qq[,3])
salva('M13','F03',ggplot(band,aes(eta,profondita_cm))+geom_ribbon(aes(xmin=lo,xmax=hi),orientation='y',fill=geo[1],alpha=.2)+geom_path(aes(x=med),colour=geo[1],linewidth=.8)+geom_point(data=d,aes(eta_cal_BP,profondita_cm),colour=geo[2],size=2.5)+ax)
a100<-apply(Aok,1,function(a)f(100,a));dur<-apply(Aok,1,function(a)diff(f(c(60,100),a)))
salva('M13','F04',ggplot(data.frame(eta=a100),aes(eta))+geom_histogram(bins=22,fill=geo[1],colour=paper)+geom_vline(xintercept=f(100),colour=geo[2],linewidth=.8)+labs(x='Età a 100 cm (cal BP)',y='Scenari'))
p$eta<-f(p$profondita_cm)
salva('M13','F05',ggplot(p,aes(profondita_cm,proxy))+geom_line(colour=geo[1],linewidth=.65)+geom_point(size=.8,colour=geo[2])+scale_x_continuous(breaks=c(0,40,80,120,160))+labs(x='Profondità (cm)',y='Proxy (u.a.)'))
salva('M13','F06',ggplot(p,aes(eta,proxy))+geom_line(colour=geo[1],linewidth=.65)+geom_point(size=.8,colour=geo[2])+scale_x_continuous(breaks=c(0,1000,2000))+labs(x='Età (cal BP)',y='Proxy (u.a.)'))
# Hiatus discontinuo a 80 cm: due rami, senza collegamento obliquo attraverso il salto.
h1<-data.frame(profondita_cm=seq(0,80,2),eta=f(seq(0,80,2)),ramo=1)
h2<-data.frame(profondita_cm=seq(80,160,2),eta=f(seq(80,160,2))+400,ramo=2);hi<-rbind(h1,h2)
salva('M13','F07',ggplot(g,aes(eta,profondita_cm))+geom_path(colour=geo[1],linewidth=.7)+geom_path(data=hi,aes(group=ramo),colour=geo[2],linewidth=.9)+annotate('segment',x=780,xend=1180,y=80,yend=80,colour=geo[2],linetype=2)+ax)
bad<-d;bad$eta_cal_BP[4]<-300
salva('M13','F08',ggplot(bad,aes(eta_cal_BP,profondita_cm))+geom_path(colour=geo[2],linewidth=.9)+geom_point(size=3,colour=geo[1])+ax)
fit<-lm(eta_cal_BP~profondita_cm,d);g$retta<-predict(fit,g)
salva('M13','F09',ggplot(g,aes(eta,profondita_cm))+geom_path(colour=geo[1],linewidth=.8)+geom_path(aes(x=retta),colour=geo[2],linewidth=.8)+geom_point(data=d,aes(eta_cal_BP,profondita_cm),size=2.5)+ax)
ii<-2:5;pr<-sapply(ii,function(i)approx(dep[-i],age[-i],xout=dep[i])$y);loo<-data.frame(profondita=dep[ii],eta=age[ii],prevista=pr,errore=pr-age[ii])
salva('M13','F10',ggplot(loo,aes(profondita,errore))+geom_hline(yintercept=0,colour=geo[6])+geom_segment(aes(xend=profondita,y=0,yend=errore),colour=geo[1],linewidth=.9)+geom_point(colour=geo[2],size=3)+scale_x_continuous(breaks=dep[ii])+labs(x='Ancora esclusa (cm)',y='Scarto di età (anni)'))
salva('M13','F11',ggplot(data.frame(durata=dur),aes(durata))+geom_histogram(bins=22,fill=geo[1],colour=paper)+geom_vline(xintercept=diff(f(c(60,100))),colour=geo[2],linewidth=.8)+scale_x_continuous(breaks=c(400,500,600),expand=expansion(mult=c(.06,.12)))+labs(x='Durata 60–100 cm (anni)',y='Scenari'))
inter<-data.frame(centro=(head(p$profondita_cm,-1)+tail(p$profondita_cm,-1))/2,anni=diff(p$eta))
salva('M13','F12',ggplot(inter,aes(centro,anni))+geom_step(colour=geo[1],linewidth=.8)+scale_x_continuous(breaks=c(0,40,80,120,160))+labs(x='Profondità centrale (cm)',y='Anni fra due campioni'))
verifica('Ancore: ordine e monotonicità',all(diff(dep)>0)&&all(diff(age)>0)&&!anyDuplicated(dep))
verifica('Interpolazione: controllo manuale a 35 cm',abs(f(35)-305)<1e-12)
verifica('Dominio: nessuna estrapolazione implicita',all(is.na(f(c(-10,180)))))
verifica('Tasso medio ponderato',abs(weighted.mean(dz/dt,dt)-sum(dz)/sum(dt))<1e-12)
verifica('Scenari monotoni mantenuti senza riordinare',nrow(Aok)>0&&all(apply(Aok,1,function(a)all(diff(a)>0))))
verifica('Proxy: valori conservati e tempi irregolari',nrow(p)==81&&length(unique(round(diff(p$eta),8)))>1)
verifica('Inversione: intervallo individuato',identical(which(diff(bad$eta_cal_BP)<=0),3L))
verifica('Esclusione interna: previsioni finite',all(is.finite(pr)))
verifica('Durate positive nello stesso scenario',all(dur>0))
# Propagazione lineare analitica prima del condizionamento di monotonicità.
w60<-c(0,0,2/3,1/3,0,0);w100<-c(0,0,0,.5,.5,0);S<-diag(d$sd_scenario_anni^2)
variance_duration<-as.numeric(t(w100-w60)%*%S%*%(w100-w60))
variance_expanded<-as.numeric(t(w100)%*%S%*%w100+t(w60)%*%S%*%w60-2*t(w100)%*%S%*%w60)
verifica('Varianza della durata con covarianza condivisa',abs(variance_duration-variance_expanded)<1e-10&&variance_duration>0)
verifica('Pesi di interpolazione a 60 e 100 cm',abs(sum(w60*age)-f(60))<1e-12&&abs(sum(w100*age)-f(100))<1e-12)
out<-'risultati/M13';dir.create(out,recursive=TRUE,showWarnings=FALSE)
write.csv(band,file.path(out,'cronologia_scenari.csv'),row.names=FALSE);write.csv(p,file.path(out,'proxy_cronologia.csv'),row.names=FALSE);write.csv(loo,file.path(out,'sensibilita_ancore.csv'),row.names=FALSE)
ix<-which.max(p$proxy);jsonlite::write_json(list(generati=500,accettati=nrow(Aok),scartati=sum(!ok),eta100_base=f(100),eta100_quantili=unname(quantile(a100,c(.025,.5,.975))),durata_base=diff(f(c(60,100))),durata_quantili=unname(quantile(dur,c(.025,.5,.975))),sd_durata_non_condizionata=sqrt(variance_duration),tasso_mm_anno=10*sum(dz)/sum(dt),picco_profondita=p$profondita_cm[ix],picco_eta=p$eta[ix],picco_hiatus=p$eta[ix]+ifelse(p$profondita_cm[ix]>80,400,0)),file.path(out,'valori.json'),auto_unbox=TRUE,pretty=TRUE,digits=12)
